import{_ as u,a0 as l,w as o,s as p,ao as r,I as s,x as n,a1 as e,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"Linux 只是一个内核：这是什么意思？ | LCTT x X-CMD","titleTemplate":false,"description":"Linux 只是一个内核：这是什么意思？ | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 只是一个内核：这是什么意思？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 只是一个内核：这是什么意思？ | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230223.1 ⭐️ Linux is Just a Kernel What Does it Mean","title":"Linux 只是一个内核：这是什么意思？","tag":"202303","desc":""},"relativePath":"202303/20230223.1 ⭐️ Linux is Just a Kernel What Does it Mean.md","filePath":"[post].md"}'),x={name:"202303/20230223.1 ⭐️ Linux is Just a Kernel What Does it Mean.md"};function d(m,t,L,f,h,b){const i=l("Link");return o(),p("div",null,[t[18]||(t[18]=r('<h1 id="linux-只是一个内核-这是什么意思" tabindex="-1">Linux 只是一个内核：这是什么意思？ <a class="header-anchor" href="#linux-只是一个内核-这是什么意思" aria-label="Permalink to “Linux 只是一个内核：这是什么意思？”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/04/085224mw1qoq5kaukqzxmz.jpg" alt=""></p><blockquote><p>这是一个困扰 Linux 用户的常见问题。这也是考试和面试中经常问到的一个问题。下面是你需要了解的所有内容。</p></blockquote><p>你可能在网络上的各种论坛以及讨论区听过这句话：</p><blockquote><p>Linux 只是一个内核。</p></blockquote><p>这让你感到好奇。它是个内核？还是个操作系统？两者之间有什么区别？</p><p>我将在本文中回答这些问题。</p><h3 id="linux-是操作系统还是内核" tabindex="-1">Linux 是操作系统还是内核？ <a class="header-anchor" href="#linux-是操作系统还是内核" aria-label="Permalink to “Linux 是操作系统还是内核？”">​</a></h3><p>好吧，<strong>从技术上讲，Linux 只是一个内核</strong>，而不是一个操作系统。但是，术语 “Linux” 通常是指一个完整的操作系统，它包括一个 <ruby>交互界面<rt>Shell</rt></ruby>（例如：bash）和命令行和/或 GUI 工具来控制系统。这个完整的操作系统的正确叫法是 “Linux 发行版”。流行的 Linux 发行版有 Ubuntu、Red Hat 和 Debian。</p><p>早在 1991 年，Linus Torvalds 创建的只是一个内核。直到今天，他也在为 Linux 内核工作。他不再编写代码，而是监督哪些代码进入内核。</p><h3 id="内核-什么东西" tabindex="-1">内核？什么东西？ <a class="header-anchor" href="#内核-什么东西" aria-label="Permalink to “内核？什么东西？”">​</a></h3><p>内核是每个操作系统的中心。不仅仅是 Linux，Windows 和 macOS 也有内核。</p><p>将内核想象成操作系统的心脏。没有心脏，你就无法生存。没有内核，操作系统就无法存在。</p><p>但是，就像心脏需要一个身体来生存一样，内核需要其他人们可以在计算机上使用的程序和工具来构成一个完整的操作系统。</p><p>这是一个操作系统的典型架构：</p><p><img src="https://itsfoss.com/content/images/2023/02/image-6.png" alt=""></p><p>在中心的内核与硬件交互。在它之上是与内核交互的 <ruby>交互界面<rt>Shell</rt></ruby>。然后你有应用程序、命令行和图形界面，为你提供使用系统的各种方式。</p><h3 id="内核是引擎-操作系统是汽车" tabindex="-1">内核是引擎，操作系统是汽车 <a class="header-anchor" href="#内核是引擎-操作系统是汽车" aria-label="Permalink to “内核是引擎，操作系统是汽车”">​</a></h3><p>一个更好的类比是将内核想象成汽车的引擎，而操作系统则是汽车。</p><p>你不可能驾驶一个引擎，但是如果没有引擎，你也不能驾驶一辆汽车。你需要轮胎、转向机和其他组件才能将其变成一辆可以驾驶的汽车。</p><p>相似地，你不能直接使用内核。你需要 <ruby>交互界面<rt>Shell</rt></ruby>，其他工具和组件才能使用操作系统。</p><p><img src="https://itsfoss.com/content/images/2023/02/image-7.png" alt=""></p><h3 id="linux-对比-gnu-linux" tabindex="-1">Linux 对比 GNU/Linux <a class="header-anchor" href="#linux-对比-gnu-linux" aria-label="Permalink to “Linux 对比 GNU/Linux”">​</a></h3>',23)),s("p",null,[t[1]||(t[1]=n("在类似的地方，你也会看到例如 “Linux 只是一个内核，",-1)),e(i,{href:"https://itsfoss.com/gnu-linux-copypasta/"},{default:a(()=>[...t[0]||(t[0]=[n("你所说的 Linux 实际上是 GNU/Linux",-1)])]),_:1}),t[2]||(t[2]=n("” 的陈述。",-1))]),t[19]||(t[19]=r('<p>在 Linus Torvalds 在 1991 年创建 Linux 之前，Richard Stallman 就创建了<ruby>自由软件运动<rt>Free Software movement</rt></ruby>和 GNU 项目。GNU 项目包括对流行的 UNIX 工具和命令的重新实现，例如 <code>ls</code>、<code>grep</code>、<code>sed</code> 等。</p><p>通常，你的 Linux 发行版会在 Linux 内核之上包含所有这些 GNU 工具。</p><p>这就是为什么纯粹主义者坚持称之为 GNU/Linux，以便人们不要忘记 GNU 对 Linux 成功的贡献和重要性。</p><h3 id="最后" tabindex="-1">最后…… <a class="header-anchor" href="#最后" aria-label="Permalink to “最后……”">​</a></h3><p><strong>所以，如果你在面试或者考试中被问到这个问题，回答 “Linux 是一个内核，而不是一个操作系统”。这是你的老师或面试官在大多数情况下想要的答案。</strong></p><p>但是更深入一点，理解内核和操作系统之间的区别。</p><p>如果有人说：“我使用 Linux”，你就会明白这个人是指 Linux 发行版，而不仅仅是内核。诚然，没有必要用 “Linux 只是一个内核，而不是一个操作系统” 来纠正别人。</p><hr>',8)),s("p",null,[t[4]||(t[4]=n("via: ",-1)),e(i,{href:"https://itsfoss.com/linux-kernel-os/"},{default:a(()=>[...t[3]||(t[3]=[n("https://itsfoss.com/linux-kernel-os/",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=n("作者：",-1)),e(i,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...t[5]||(t[5]=[n("Abhishek Prakash",-1)])]),_:1}),t[10]||(t[10]=n(" 选题：",-1)),e(i,{href:"https://github.com/lkxed/"},{default:a(()=>[...t[6]||(t[6]=[n("lkxed",-1)])]),_:1}),t[11]||(t[11]=n(" 译者：",-1)),e(i,{href:"https://github.com/Cubik65536"},{default:a(()=>[...t[7]||(t[7]=[n("Cubik65536",-1)])]),_:1}),t[12]||(t[12]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[n("LCTT",-1)])]),_:1}),t[16]||(t[16]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[n("Linux中国",-1)])]),_:1}),t[17]||(t[17]=n(" 荣誉推出",-1))])])}const C=u(x,[["render",d]]);export{k as __pageData,C as default};
